{
 "command": "make test-fast 2>&1 | tail -40",
 "description": "Run fast test suite"
}

{
 "command": "cat tests/fxdata.py; grep -rn \"FX_FIXTURES\" --exclude-dir=.git . | head; ls; ls tests",
 "description": "Find the fixtures env var usage"
}

{
 "mode": "filter",
 "query": "LEDGERLINE_FX_FIXTURES fx fixtures"
}

{
 "command": "LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -30",
 "description": "Rerun fast tests with FX fixtures path set"
}

{
 "command": "ls -R tests/fixtures | head -30; cat docs/testing.md; git log --stat --oneline | head -30",
 "description": "Inspect fixtures, docs and history"
}

{
 "command": "python scripts/gen_fx_fixtures.py && LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -30; git status --short",
 "description": "Generate FX fixtures and rerun fast tests"
}

